WITH enriched AS (SELECT *, LAST_VALUE(amount, TRUE) OVER (ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, AVG(amount) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3, FIRST_VALUE(method, TRUE) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method FROM payments) SELECT s.id, s.order_id, s.method, s.amount, s.paid_at, s.amount_avg_3, CASE WHEN method RLIKE '^(bank_transfer|cash)$' THEN 'OTHER_ZONE' WHEN method RLIKE '^(card|paypal)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS method_zone, (SELECT MAX(x.unit_price) FROM order_items x WHERE x.order_id = s.order_id) AS max_order_item_unit_price FROM enriched s
